package com.primehr.security;import com.primehr.integration.administrative.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Component;@Component public class PerformanceSuccessIndicatorPermissionGuard{public static final String FEATURE="primehr.performance-success-indicator";private final AdministrativeAuthorizationClient client;public PerformanceSuccessIndicatorPermissionGuard(AdministrativeAuthorizationClient c){client=c;}public void require(PrimeHrAction a,String t){EffectiveFeaturePermission p=client.resolve(FEATURE,t);boolean ok=p.administrator()||p.canAccess()&&switch(a){case ACCESS->true;case ADD->p.canAdd();case EDIT->p.canEdit();case PUBLISH->p.canPublish();default->false;};if(!ok||!p.administrator()&&p.dataScope()!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Performance success indicators require agency-wide permission");}}
